def sort(a):
    if len(a) <= 1:
        return a
    pivot = a[len(a) // 2]              # choose a pivot
    less    = [x for x in a if x < pivot]
    equal   = [x for x in a if x == pivot]
    greater = [x for x in a if x > pivot]
    return sort(less) + equal + sort(greater)

